P.rep('''# 0.3.24 ABILITY LEVELS: SkyyClasses 0.1.22's class:fn:abilPanel apply(UUID) -> Object[78]: [0] "ok", [8] Boolean levels on, per slot i
# (p1, p2, a1, a2 - the class:fn:abil order) at b = 12 + 16 i: [b] ability id, [b + 6] Integer level. -> { String[4] ids, long[4] levels }
# (id null / level 0 = nothing to show). Anything else (no SkyyClasses 0.1.22, levels off, a short or odd answer) = nothing.
wid.addMethod(CtNewMethod.make("""
public static Object[] abilLvOf(Object r) {
  String[] ids = new String[4];
  long[] lv = new long[4];
  Object[] out = new Object[] { ids, lv };
  if (!(r instanceof Object[])) return out;
  Object[] o = (Object[]) r;
  if (o.length < 76 || !"ok".equals(o[0]) || !Boolean.TRUE.equals(o[8])) return out;
  for (int i = 0; i < 4; i++) {
    int bi = 12 + 16 * i;
    Object id = o[bi];
    Object l = o[bi + 6];
    if (id instanceof String && ((String) id).length() > 0 && l instanceof Number && ((Number) l).longValue() > 0L) {
      ids[i] = (String) id;
      lv[i] = ((Number) l).longValue();
    }
  }
  return out;
}""", wid))''', '''# 0.3.24 ABILITY LEVELS: SkyyClasses 0.1.22's class:fn:abilPanel apply(UUID) -> Object[78]: [0] "ok", [8] Boolean levels on, per slot i
# (p1, p2, a1, a2 - the class:fn:abil order) at b = 12 + 16 i: [b] ability id, [b + 6] Integer level. -> { String[4] ids, long[4] levels }
# (id null / level 0 = nothing to show). Anything else (no SkyyClasses 0.1.22, levels off, a short or odd answer) = nothing.
# 0.3.32: -> { String[4] ids, long[4] levels, String[4] icons }: [b + 2] = the ability's icon item id (SkyyClasses 0.1.36 AbilDefs.ICON, ""
# when not loaded); ids + icons are kept while levels are off ([8] false) - a level still needs [8] true and a value above 0
wid.addMethod(CtNewMethod.make("""
public static Object[] abilLvOf(Object r) {
  String[] ids = new String[4];
  long[] lv = new long[4];
  String[] ic = new String[4];
  Object[] out = new Object[] { ids, lv, ic };
  if (!(r instanceof Object[])) return out;
  Object[] o = (Object[]) r;
  if (o.length < 76 || !"ok".equals(o[0])) return out;
  boolean lvOn = Boolean.TRUE.equals(o[8]);
  for (int i = 0; i < 4; i++) {
    int bi = 12 + 16 * i;
    Object id = o[bi];
    Object l = o[bi + 6];
    if (!(id instanceof String) || ((String) id).length() == 0) continue;
    ids[i] = (String) id;
    ic[i] = abilIdOk(o[bi + 2]);
    if (lvOn && l instanceof Number && ((Number) l).longValue() > 0L) lv[i] = ((Number) l).longValue();
  }
  return out;
}""", wid))''')
